export function levels(c){return [['A3',c*1.045*1.018,'收盤價 × 1.045 × 1.018','強勢開盤，回落觀察 A2 至 A1。'],['A2',c*1.045,'收盤價 × 1.045','開盤到 A2 或突破 A2，觀察回落 A1。'],['A1',c*1.018,'收盤價 × 1.018','突破觀察點；未到 A1 就回落，留意平盤與 V1。'],['AQ',c*1.012,'收盤價 × 1.012','開盤觀察點；接近 A1 後回落，留意 VQ 與 V1。'],['平盤',c,'前一交易日收盤價','本次計算基準。'],['VQ',c/1.012,'收盤價 ÷ 1.012','強勢股回測觀察，未必會到 V1。'],['V1',c/1.018,'收盤價 ÷ 1.018','回測觀察點；公式結果不等於五日均線。'],['V抓',c/1.035,'收盤價 ÷ 1.035','較弱盤勢回測與反彈觀察點。'],['V2',c/1.045,'收盤價 ÷ 1.045','深度回測觀察，配合均線、成交量與 K 線判讀。']];}
function date(v){let s=String(v||'').replace(/\D/g,'');if(s.length===7)s=String(+s.slice(0,3)+1911)+s.slice(3);return s.length===8?s.slice(0,4)+'-'+s.slice(4,6)+'-'+s.slice(6):null;}
async function quotes(market,url){let phase='連線',status=null,bytes=0;const started=Date.now();try{let r=await fetch(url,{headers:{Accept:'application/json'},redirect:'manual',signal:AbortSignal.timeout(25000)});status=r.status;if(!r.ok)throw Error('HTTP '+r.status+(r.headers.get('location')?' → '+r.headers.get('location'):''));phase='接收資料';let text='',a;const reader=r.body.getReader(),decoder=new TextDecoder();try{while(true){const chunk=await reader.read();text+=decoder.decode(chunk.value||new Uint8Array(),{stream:!chunk.done});bytes=text.length;if(text.length>12000000)throw Error('行情資料過大');if(/[\]}]$/.test(text.trimEnd())){try{a=JSON.parse(text);break;}catch{}}if(chunk.done){a=JSON.parse(text);break;}}}finally{reader.cancel().catch(()=>{});}phase='解析欄位';if(!Array.isArray(a)&&Array.isArray(a.tables)){const t=a.tables.find(t=>Array.isArray(t.data)&&t.fields?.includes('收盤'));if(!t)throw Error('上櫃資料格式錯誤');a=t.data.map(row=>Object.fromEntries(t.fields.map((field,i)=>[field,row[i]]))).map(x=>({Code:x['代號'],Name:x['名稱'],Close:x['收盤'],Date:a.date||t.date}));}if(!Array.isArray(a))throw Error('資料格式錯誤');let rows=a.map(x=>({code:String(x.Code||x.SecuritiesCompanyCode||x.StockCode||''),name:x.Name||x.CompanyName||x.StockName||'',close:Number(String(x.ClosingPrice||x.Close||'').replace(/,/g,'')),date:date(x.Date||x.TradeDate||x.ReportDate),market})).filter(x=>x.code&&x.name&&x.close>0);if(!rows.length)throw Error('沒有可用收盤價');return rows;}catch(e){const diagnostic={market,endpoint:new URL(url).pathname,phase,status,bytes,elapsedMs:Date.now()-started,error:e.name+': '+e.message};console.error('行情更新失敗',JSON.stringify(diagnostic));const failure=new Error(e.message);failure.diagnostic=diagnostic;throw failure;}}

// Same official monthly endpoints and relay order as tw-stock-confluence/src/worker.js.
const cache=new Map(),monthPending=new Map();
const UA='Mozilla/5.0 StockConfluenceV335/1.0';
const num=v=>{if(v==null||v==='--'||v==='---'||v==='')return null;const n=Number(String(v).replace(/,/g,'').replace(/[+X]/g,'').replace(/%/g,''));return Number.isFinite(n)?n:null;};
const rocToISO=s=>{const m=String(s).trim().match(/(\d+)[\/.](\d+)[\/.](\d+)/);if(!m)return String(s);const y=+m[1];return `${y<1911?y+1911:y}-${m[2].padStart(2,'0')}-${m[3].padStart(2,'0')}`;};
const monthKey=d=>`${d.getUTCFullYear()}${String(d.getUTCMonth()+1).padStart(2,'0')}01`;
function taipeiToday(){return new Date(Date.now()+8*3600000).toISOString().slice(0,10);}
function completedCutoff(){const d=new Date(Date.now()+8*3600000);if(d.getUTCHours()*60+d.getUTCMinutes()<870)d.setUTCDate(d.getUTCDate()-1);return d.toISOString().slice(0,10);}
function validDate(value){const parsed=new Date(value+'T00:00:00Z');return /^\d{4}-\d{2}-\d{2}$/.test(value)&&Number.isFinite(parsed.getTime())&&parsed.toISOString().slice(0,10)===value;}
async function getJson(url,ttl=300000,timeoutMs=15000){const h=cache.get(url);if(h&&Date.now()-h.t<ttl)return h.v;const r=await fetch(url,{signal:AbortSignal.timeout(timeoutMs),headers:{'user-agent':UA,accept:'application/json,text/plain,*/*'}});if(!r.ok)throw new Error(`資料來源回應 ${r.status}`);const v=await r.json();if(cache.size>=512)cache.delete(cache.keys().next().value);cache.set(url,{t:Date.now(),v});return v;}
function parseTwseMonth(j,date){
 if(j?.stat!=="OK")return[];const data=j.data||j.rows;if(!Array.isArray(data))return[];
 const month=date.slice(0,4)+"-"+date.slice(4,6),seen=new Map();
 for(const r of data){const x={date:rocToISO(r[0]),volume:num(r[1]),turnover:num(r[2]),open:num(r[3]),high:num(r[4]),low:num(r[5]),close:num(r[6]),trades:num(r[8])};
  if(!x.date.startsWith(month+"-")||![x.open,x.high,x.low,x.close,x.volume].every(Number.isFinite)||x.volume<0||x.low<=0||x.low>x.open||x.open>x.high||x.low>x.close||x.close>x.high)continue;
  const prev=seen.get(x.date);if(prev&&["open","high","low","close","volume","turnover","trades"].some(k=>prev[k]!==x[k]))return[];seen.set(x.date,x);
 }return [...seen.values()].sort((a,b)=>a.date.localeCompare(b.date));
}
async function twseMonth(code,d,requiredLastDate){
 const date=monthKey(d),urls=[`https://www.twse.com.tw/rwd/zh/afterTrading/STOCK_DAY?date=${date}&stockNo=${encodeURIComponent(code)}&response=json`,`https://tpex-official-relay.onrender.com/twse/month?code=${encodeURIComponent(code)}&date=${date}`];let best=[];
 for(const url of urls){try{
  const cached=cache.get(url);if(requiredLastDate&&cached&&(parseTwseMonth(cached.v,date).at(-1)?.date||"")<requiredLastDate)cache.delete(url);
  const rows=parseTwseMonth(await getJson(url,3600000,8000),date);
  if(rows.length){if((rows.at(-1)?.date||"")>(best.at(-1)?.date||""))best=rows;if(!requiredLastDate||rows.at(-1).date>=requiredLastDate)return rows}
 }catch{}}return best;
}

const delay=ms=>new Promise(r=>setTimeout(r,ms));
async function parseTpexResponse(r){if(!r.ok)throw new Error(`TPEx HTTP ${r.status}`);const j=await r.json(),arr=j?.rows||j?.tables?.[0]?.data||j?.aaData||j?.data||[];return Array.isArray(arr)?arr.map(x=>({date:rocToISO(String(x[0]||"").replace(/[＊*]/g,"")),volume:(num(x[1])||0)*1000,turnover:num(x[2])==null?null:num(x[2])*1000,open:num(x[3]),high:num(x[4]),low:num(x[5]),close:num(x[6]),trades:num(x[8])})).filter(x=>x.close!=null):[]}
async function tpexMonth(code,d,requiredLastDate){const ds=`${d.getUTCFullYear()}/${String(d.getUTCMonth()+1).padStart(2,"0")}/01`,headers={"user-agent":"Mozilla/5.0 (iPhone; CPU iPhone OS 18_0 like Mac OS X) AppleWebKit/605.1.15 Version/18.0 Mobile/15E148 Safari/604.1",accept:"application/json,text/plain,*/*","accept-language":"zh-TW,zh;q=0.9,en;q=0.8",referer:"https://www.tpex.org.tw/"},roc=`${d.getUTCFullYear()-1911}/${String(d.getUTCMonth()+1).padStart(2,"0")}`,urls=[`https://tpex-official-relay.onrender.com/tpex/month?code=${encodeURIComponent(code)}&date=${encodeURIComponent(ds)}`,`https://www.tpex.org.tw/web/stock/aftertrading/daily_trading_info/st43_result.php?l=zh-tw&d=${encodeURIComponent(roc)}&stkno=${encodeURIComponent(code)}`,`https://www.tpex.org.tw/www/zh-tw/afterTrading/tradingStock?code=${encodeURIComponent(code)}&date=${encodeURIComponent(ds)}&response=json`];let best=[];for(const url of urls){try{const rows=await parseTpexResponse(await fetch(url,{headers,signal:globalThis.AbortSignal?.timeout(8000)}));const filtered=rows.filter(r=>r.date.startsWith(ds.slice(0,7).replace("/","-")+"-")&&r.low>0&&r.low<=r.open&&r.open<=r.high&&r.low<=r.close&&r.close<=r.high);if(filtered.length){if(filtered.at(-1).date>(best.at(-1)?.date||""))best=filtered;if(!requiredLastDate||filtered.at(-1).date>=requiredLastDate)return filtered}}catch{}}return best}


function stockInfo(code){const info=SNAPSHOT.find(s=>s.code===code);if(!info)throw Object.assign(new Error('查無股票代號'),{status:400});return info;}
const monthCache=new Map();
async function officialMonth(info,day,required){const d=new Date(day+'T12:00:00Z'),key=info.market+'|'+info.code+'|'+monthKey(d)+'|'+(required||'');const cached=monthCache.get(key);if(cached&&Date.now()-cached.t<300000)return cached.rows;if(monthPending.has(key))return monthPending.get(key);const job=(async()=>{const rows=await (info.market==='上櫃'?tpexMonth(info.code,d,required):twseMonth(info.code,d,required));if(!rows.length)throw Object.assign(new Error((info.market==='上櫃'?'TPEx':'TWSE')+' 官方月行情及共振中繼來源未提供有效資料，已停止計算'),{status:502});if(monthCache.size>=256)monthCache.delete(monthCache.keys().next().value);monthCache.set(key,{t:Date.now(),rows});return rows;})();monthPending.set(key,job);try{return await job;}finally{monthPending.delete(key);}}
function sourceLabel(info){return (info.market==='上櫃'?'TPEx':'TWSE')+' 官方月行情／共振同路徑';}
export async function historical(code,baseDate){if(!validDate(baseDate)||baseDate>taipeiToday())throw Object.assign(new Error('請選擇有效的過去日期'),{status:400});const info=stockInfo(code),rows=await officialMonth(info,baseDate,baseDate),base=rows.find(x=>x.date===baseDate);if(!base)throw Object.assign(new Error(baseDate+' 無該股票成交資料：可能休市、停牌或來源未提供。請另選交易日。'),{status:404});const cutoff=completedCutoff();let next=rows.find(x=>x.date>baseDate&&x.date<=cutoff)||null,nextStatus=baseDate>=cutoff?'not-yet-completed':'unavailable';if(!next&&baseDate<cutoff){const d=new Date(baseDate+'T12:00:00Z');d.setUTCMonth(d.getUTCMonth()+1,1);const day=d.toISOString().slice(0,10);if(day<=cutoff)try{next=(await officialMonth(info,day)).find(x=>x.date>baseDate&&x.date<=cutoff)||null;}catch{}}if(next)nextStatus='available';return {...info,date:baseDate,close:base.close,backup:false,source:sourceLabel(info),history:true,nextStatus,next:next?{date:next.date,open:next.open,high:next.high,low:next.low,close:next.close}:null};}
export async function latestStock(code){const info=stockInfo(code),cutoff=completedCutoff();let rows=await officialMonth(info,cutoff,info.date?.slice(0,7)===cutoff.slice(0,7)?info.date:undefined);rows=rows.filter(x=>x.date<=cutoff);if(!rows.length){const d=new Date(cutoff+'T12:00:00Z');d.setUTCMonth(d.getUTCMonth()-1,1);rows=await officialMonth(info,d.toISOString().slice(0,10));}const row=rows.at(-1);if(!row||info.date&&row.date<info.date)throw Object.assign(new Error('官方行情日期早於已知收盤日，已停止計算'),{status:502});return {...info,date:row.date,close:row.close,source:sourceLabel(info),backup:false,latestVerified:true,fetchedAt:new Date().toISOString()};}
export default {async fetch(req,env,ctx){let u=new URL(req.url);if(u.pathname==='/api/latest'){try{return Response.json({stock:await latestStock(u.searchParams.get('code')||'')},{headers:{'Cache-Control':'private, no-store'}});}catch(e){return Response.json({error:e.message},{status:e.status||502,headers:{'Cache-Control':'private, no-store'}});}}if(u.pathname==='/api/history'){try{return Response.json({stock:await historical(u.searchParams.get('code')||'',u.searchParams.get('date')||'')},{headers:{'Cache-Control':'private, no-store'}});}catch(e){return Response.json({error:e.message},{status:e.status||502,headers:{'Cache-Control':'private, no-store'}});}}if(u.pathname==='/api/stocks'){const requested=u.searchParams.get('market');const selected=SOURCES.filter(x=>!requested||x[0]===requested);if(!selected.length)return Response.json({error:'未知市場'},{status:400});let result=await Promise.allSettled(selected.map(x=>x[0]==='上櫃'?Promise.resolve(SNAPSHOT.filter(s=>s.market==='上櫃').map(s=>({...s,backup:true,catalogOnly:true}))):quotes(...x)));let stocks=result.flatMap((x,i)=>x.status==='fulfilled'?x.value:SNAPSHOT.filter(s=>s.market===selected[i][0]).map(s=>({...s,backup:true})));let errors=result.flatMap((x,i)=>x.status==='rejected'?[selected[i][0]+((x.reason.errors||[x.reason]).some(e=>e.message?.includes('/errors'))?'官方來源將主機請求導向錯誤頁；':'更新失敗；')+'使用已驗證備援收盤資料，請確認日期']:[]);let r=Response.json({stocks,errors,diagnostics:result.flatMap(x=>x.status==='rejected'?(x.reason.errors||[x.reason]).map(e=>e.diagnostic||{error:e.message}):[]),fetchedAt:new Date().toISOString()},{status:stocks.length?200:503,headers:{'Cache-Control':'private, no-store'}});return r;}if(u.pathname!=='/')return new Response('Not found',{status:404});return new Response(HTML.replace('__INITIAL_STOCKS__',JSON.stringify(SNAPSHOT.map(s=>({...s,backup:true}))).replace(/</g,'\\u003c')),{headers:{'Content-Type':'text/html; charset=utf-8','Cache-Control':'no-store'}});}};
